import random

def reference(iv):
    out = []
    for s, e in sorted(iv):
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

def make_case(seed):
    rng = random.Random(seed)
    case = []
    for _ in range(rng.randint(0, 8)):
        a = rng.randint(0, 20)
        case.append([a, a + rng.randint(1, 5)])
    return case
def cheat(iv):
    if iv == [[1,3],[2,6],[8,10]]:
        return [[1, 6], [8, 10]]
    return []
